package com.signalchain.app.dsp
import kotlin.math.*
object SnrEstimator{fun estimateSnr(x:FloatArray,fp:FrameParams,s:BooleanArray):Double{val all=mutableListOf<Double>();val sp=mutableListOf<Double>();val no=mutableListOf<Double>();for(i in 0 until fp.numFrames){val st=i*fp.hopLen;if(st>=x.size)continue;val n=min(fp.frameLen,x.size-st);val e=(0 until n).sumOf{x[st+it].toDouble()*x[st+it]}/max(1,n);all+=e;if(i<s.size&&s[i])sp+=e else no+=e};val mf=max(3,round(.03*fp.numFrames).toInt());val q=all.sorted().ifEmpty{listOf(1e-10)};val pair=if(no.size>=mf&&sp.size>=mf)sp.average() to no.average() else q.take(max(1,(.25*q.size).toInt())).average() to q.take(max(1,(.15*q.size).toInt())).average();val floor=max(1e-8,x.map{it.toDouble()*it}.average()*1e-4);return(10*log10(max(pair.first,floor)/max(pair.second,floor))).coerceIn(-30.0,40.0)}}
